pragma solidity ^0.8.0;
contract Airdrop {
    function SendToAll(address payable [] memory recipients, uint256 Amount)
    public payable  {
        for (uint256 i =0; i < recipients.length; i++ ) {
            recipients [i] . transfer (Amount);
        }

    }

}

